function AutoChessMode.prototype.endGame(self)
    self.gameState.isGameActive = false
    local gameWinner = "enemy"
    for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
        local playerId = ____value[1]
        local playerState = ____value[2]
        if playerState.isAlive and playerState.health > 0 then
            self.gameState.winnerPlayerId = playerId
            gameWinner = "player"
            break
        end
    end
    print((("[AutoChessMode] Game ended. Winner: " .. gameWinner) .. ", Round: ") .. tostring(self.gameState.currentRound))
    for ____, ____value in __TS__Iterator(self.gameState.playerStates) do
        local playerId = ____value[1]
        local playerState = ____value[2]
        local settlementData = {
            round = self.gameState.currentRound,
            winner = playerState.isAlive and playerState.health > 0 and "player" or "enemy",
            rewardGold = 0,
            availableStages = {},
            playerSummary = self:buildPlayerSummary(),
            stats = {},
            levelName = nil,
            isGameOver = true
        }
        print("[AutoChessMode] 📤 Sending game over settlement to player " .. tostring(playerId))
        local player = PlayerResource:GetPlayer(playerId)
        if player then
            CustomGameEventManager:Send_ServerToPlayer(player, "autochess_wave_settlement", settlementData)
            print("[AutoChessMode] ✅ Game over settlement sent to player " .. tostring(playerId))
        end
    end
