function AutoChessMode.prototype.registerEvents(self)
    print("[AutoChessMode] Registering events...")
    CustomGameEventManager:RegisterListener(
        "battle_completed",
        function(userId, data)
            print("[AutoChessMode] battle_completed from client! userId: " .. tostring(userId))
            self:handleBattleCompleted(data)
        end
    )
    print("[AutoChessMode] Events registered successfully")
end
function AutoChessMode.prototype.handleBattleCompleted(self, data)
