    local currentState = GameRules:State_Get()
    print("[AutoChessMode] 当前游戏状态: " .. tostring(currentState))
    if currentState >= 5 then
        print("[AutoChessMode] 游戏已在进行中，立即尝试激活...")
        Timers:CreateTimer(
            1,
            function()
                if not self.isActive then
